import React, { Component } from 'react';
import { requestHeaderPOSTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import {
    CButton,
    CCard,
    CCardBody,
    CCardGroup,
    CCol,
    CContainer,
    CForm,
    CInput,
    CInputGroup,
    CInputGroupPrepend,
    CInputGroupText,
    CRow,
} from '@coreui/react';
import CIcon from '@coreui/icons-react';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';

const FILE_NAME = "YoutubeMetadataExtractor.js";

const initialState = {
    isLoaded: true,
    loadingModalVisible: false,
    loadingModalState: 0,
    failureModalVisible: false,
    urlInputValue: '',
    isProcessing: false,
};

class YoutubeMetadataExtractor extends Component {

    constructor(props) {
        super(props);
        this.state = JSON.parse(JSON.stringify(initialState));
    }

    resetStateToDefault() {
        this.setState(JSON.parse(JSON.stringify(initialState)));
    }

    reloadData() {
        this.resetStateToDefault();
    }

    componentDidMount() {
        document.title = "YouTube Metadata Extractor";
        this.pasteFromClipboard();
    }

    pasteFromClipboard = async () => {
        try {
            const text = await navigator.clipboard.readText();
            if (text) {
                this.setState({ urlInputValue: text });
            }
        } catch (err) {
            Logger(FILE_NAME, "pasteFromClipboard", "", "clipboard read failed", err);
        }
    }

    handleUrlInputChange = (event) => {
        this.setState({ urlInputValue: event.target.value });
    }

    submitYoutubeForm = (event) => {
        event.preventDefault();

        const url = this.state.urlInputValue.trim();
        if (!url) {
            toast("❌ Please enter a YouTube URL");
            return;
        }

        let reqData = {
            url: url,
            shouldDownload: event.target.inputShouldDownload.checked,
        };

        Logger(FILE_NAME, "submitYoutubeForm", "", "reqData", reqData);

        this.setState({
            loadingModalVisible: true,
            loadingModalState: 0,
            isProcessing: true,
        });

        this.callSubmitYoutubeApi(reqData);
    }

    callSubmitYoutubeApi(reqData) {
        let API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/youtube/process?from=admin-portal';
        const userData = getUserDataFromLocalStorage();

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            this.setState({
                loadingModalVisible: false,
                loadingModalState: 0
            });
            if (response.status === 200) {
                return response.json().then(result => {
                    Logger(FILE_NAME, "callSubmitYoutubeApi", "FETCH_1", "result", result);
                    const message = result.data || 'Success';
                    toast("200 : ✅ : " + message);
                    alert(`✅ [${response.status}] ${message}`);
                    this.setState({ loadingModalState: 1 });
                    reloadPage();
                });
            } else {
                return response.text().then(text => {
                    toast(response.status + " : ❌ : " + text);
                    alert(`❌ [${response.status}] ${text}`);
                    reloadPage();
                });
            }
        })
        .catch(
            (error) => {
                Logger(FILE_NAME, "callSubmitYoutubeApi", "FETCH_1", "error", error);
                toast("❌ Error: " + error.message);
                alert(`❌ [Error] ${error.message}`);
                this.setState({
                    loadingModalVisible: false,
                    loadingModalState: 0,
                    failureModalVisible: true
                });
            }
        )
        .finally(() => {
            this.setState({ isProcessing: false });
        });
    }

    render() {
        Logger(FILE_NAME, "render", "", "this.state", this.state);

        return (
            this.state.isLoaded ?
            <div>
                <h1>YouTube Metadata Extractor &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;
                    <CButton color="secondary" className="px-4" onClick={() => this.props.history.push('/youtube')}>← Back</CButton>
                </h1>
                <br />

                <CContainer>
                <CRow className="justify-content-center">
                <CCol md="8">
                    <CCardGroup>
                    <CCard className="p-4">
                        <CCardBody>
                        <CForm onSubmit={this.submitYoutubeForm}>
                            <h1>Submit a YouTube video URL - to extract metadata</h1>
                            <CInputGroup className="mb-3">
                                <CInputGroupPrepend>
                                    <CInputGroupText>
                                    Link
                                    </CInputGroupText>
                                </CInputGroupPrepend>
                                <CInput
                                    placeholder="Paste YouTube URL here..."
                                    autoComplete="on"
                                    type="text"
                                    id="inputUrl"
                                    label="YouTube video URL"
                                    value={this.state.urlInputValue}
                                    onChange={this.handleUrlInputChange}
                                    required
                                />
                            </CInputGroup>

                            <CRow className="mb-3">
                                <CCol>
                                    <CButton
                                        color="secondary"
                                        size="sm"
                                        onClick={this.pasteFromClipboard}
                                    >
                                        📋 Paste from clipboard
                                    </CButton>
                                </CCol>
                            </CRow>

                            <CInputGroup className="mb-3">
                                <CInputGroupPrepend>
                                    <CInputGroupText>
                                        Should Download
                                    </CInputGroupText>
                                </CInputGroupPrepend>
                                <CInput
                                    type="checkbox"
                                    defaultValue='false'
                                    id='inputShouldDownload'
                                    label="Should Download"
                                    style={{ width: "30px", height: "30px", marginLeft: "10px" }}
                                />
                            </CInputGroup>

                            <CRow>
                                <CCol xs="6">
                                    <CButton
                                        color="success"
                                        className="px-4"
                                        size="lg"
                                        type="submit"
                                        disabled={this.state.isProcessing}
                                    >
                                        {this.state.isProcessing ? 'Processing...' : 'SUBMIT'}
                                    </CButton>
                                </CCol>
                                <CCol xs="6" className="text-right">
                                    <CButton color="danger" className="px-0" onClick={() => this.reloadData()}>&nbsp;Reset&nbsp;</CButton>
                                </CCol>
                            </CRow>
                        </CForm>
                        </CCardBody>
                    </CCard>
                    </CCardGroup>
                </CCol>
                </CRow>
                </CContainer>

                <CContainer className="mt-4">
                    <CRow className="justify-content-center">
                        <CCol md="4" className="text-center mb-3">
                            <img
                                src="https://i.ytimg.com/vi/UnURElCzGc0/hqdefault.jpg" 
                                alt="Sample YouTube video Thumbnail"
                                style={{ borderRadius: "8px", maxWidth: "100%", maxHeight: "300px" }}
                            />
                        </CCol>
                        <br />
                        <CCol md="4" className="text-center mb-3">
                            <img
                                src="https://yt3.ggpht.com/ytc/AIdro_nERCwRqFFkWNH-6teSqEiguDFW2WVgZ5pD224oP0ERSUM=s800-c-k-c0x00ffffff-no-rj"
                                alt="Sample YouTube channel Thumbnail"
                                style={{ borderRadius: "8px", maxWidth: "100%", maxHeight: "300px" }}
                            />
                        </CCol>
                    </CRow>
                </CContainer>

                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
                <ToastContainer
                    position="bottom-right"
                    autoClose={20000}
                    style={{ width: "50%", fontSize: "13px" }}
                />
            </div>
            : <Loading />
        );
    }
}

export default YoutubeMetadataExtractor;
